package ro.leo.visual;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.*;import java.util.*;
/** One explicit recurring Calendar Leo event per contact lookup key, at 09:00. */
final class BirthdaySync {
 static long next(int month,int day,long now){Calendar reference=Calendar.getInstance();reference.setTimeInMillis(now);int first=reference.get(Calendar.YEAR);for(int year=first;year<first+9;year++){Calendar d=Calendar.getInstance();d.clear();d.setLenient(false);try{d.set(year,month,day,9,0);long time=d.getTimeInMillis();if(time>now)return time;}catch(IllegalArgumentException ignored){}}throw new IllegalArgumentException();}
 static long sync(Context c,long raw,long contact)throws Exception{String date=ContactExtras.birthday(c,raw);int[] md=ContactExtras.monthDay(date);String title="",lookup="";try(Cursor r=c.getContentResolver().query(ContentUris.withAppendedId(ContactsContract.Contacts.CONTENT_URI,contact),new String[]{"display_name","lookup"},null,null,null)){if(r==null||!r.moveToFirst())throw new IllegalArgumentException();title=r.getString(0);lookup=r.getString(1);}if(lookup==null||lookup.isEmpty())throw new IllegalArgumentException();long calendar=CalendarArchive.ensure(c);String key="leo-birthday:"+Uri.encode(lookup);long id=-1;try(Cursor r=c.getContentResolver().query(CalendarContract.Events.CONTENT_URI,new String[]{"_id"},"calendar_id=? AND deleted=0 AND customAppPackage=? AND customAppUri=?",new String[]{""+calendar,c.getPackageName(),key},null)){if(r!=null&&r.moveToFirst())id=r.getLong(0);}ContentValues v=new ContentValues();v.put("calendar_id",calendar);v.put("title","Aniversare · "+title);v.put("dtstart",next(md[0],md[1],System.currentTimeMillis()));v.put("duration","PT3600S");v.putNull("dtend");v.put("rrule","FREQ=YEARLY");v.put("eventTimezone",TimeZone.getDefault().getID());v.put("customAppPackage",c.getPackageName());v.put("customAppUri",key);if(id<0){v.put("hasAlarm",0);Uri added=c.getContentResolver().insert(CalendarContract.Events.CONTENT_URI,v);if(added==null)throw new IllegalStateException();id=ContentUris.parseId(added);}else c.getContentResolver().update(ContentUris.withAppendedId(CalendarContract.Events.CONTENT_URI,id),v,null,null);CalendarReminders.schedule(c);return id;}
}
